const rows=Array.from({length:target.length+1},()=>Array(spoken.length+1).fill(0));for(let i=1;i<=target.length;i++)for(let j=1;j<=spoken.length;j++)rows[i][j]=target[i-1]===spoken[j-1]?rows[i-1][j-1]+1:Math.max(rows[i-1][j],rows[i][j-1]);
