 n.answers ||= {};n.mistakes ||= {};const prev=n.answers[q.id]||{};
 n.answers[q.id]={correct:ok,answer:clone(a.draft),attempts:(prev.attempts||0)+1,firstCorrect:prev.firstCorrect??(ok&&!a.helped.includes(q.id)),updatedAt:Date.now()};
