const reviewKey=()=>`evo.course.a2.review.v1.${reviewUser}`;
function loadReview(){try{review=R.restore(localStorage.getItem(reviewKey()));}catch(_){review=R.initial();}}
function persistReview(){try{localStorage.setItem(reviewKey(),JSON.stringify(review));}catch(_){cardNotice=cr('saveError');}}
function siteClient(){try{return window.parent?.supabaseClient||window.parent?.supabase||null;}catch(_){return null;}}
async function loadSavedCards(){savedCards=[];const client=siteClient();if(!client?.auth?.getUser)return;try{const {data:{user}={},error:userError}=await client.auth.getUser();if(userError||!user){if(reviewUser!=='guest'){reviewUser='guest';loadReview();}return;}const id=String(user.id);if(reviewUser!==id){reviewUser=id;loadReview();}const {data,error}=await client.from('cards').select('word,translation').eq('user_id',id).limit(500);if(error)throw error;savedCards=Array.isArray(data)?data:[];}catch(_){cardNotice=cr('syncUnavailable');}}
function availableCards(){const unlocked=B.lessons.filter((_,i)=>E.unlocked(state,i));let local=[];if(reviewUser==='guest')try{local=JSON.parse(localStorage.getItem('evo.course.a2.cards')||'[]').map(word=>({word,translation:''}));}catch(_){}return R.merge(R.catalogue(unlocked),[...savedCards,...local]);}
function dailyCount(){return (review.days[E.localDay()]||[]).length;}
async function openCards(scope='due'){cardReturn=scope==='lesson'?'vocabulary':'map';cardLoading=true;cardNotice='';view='cards';render();await loadSavedCards();const all=availableCards(),today=E.localDay();cardDeck=scope==='lesson'?all.filter(c=>c.lesson===B.lessons[state.active.lesson].id):R.due(all,review,today,5);cardIndex=0;cardRevealed=false;cardFeedback=null;cardInput='';cardLoading=false;render();}
function cardCurrent(){return cardDeck[cardIndex]||null;}
function cardPrompt(card){return card.translation||card.clue||card.word;}
function cardScreen(){const card=cardCurrent(),count=cardDeck.length,finished=!card&&!cardLoading,goal=Math.min(5,dailyCount());app.innerHTML=`<div class="lesson-flow"><div class="flow-top"><button type="button" class="quiet" data-action="cards-exit">← ${esc(t('map'))}</button><span class="pill">${esc(cr('reviewWords'))}</span><div class="progress" role="progressbar" aria-label="${esc(cr('reviewWords'))}" aria-valuemin="0" aria-valuemax="${Math.max(count,1)}" aria-valuenow="${Math.min(cardIndex,count)}"><i style="width:${count?100*cardIndex/count:0}%"></i></div><span class="small">${card?cardIndex+1:count}/${count}</span></div><section class="lesson-card flow-card review-card"><div class="review-head"><span class="pill">${esc(card?.source?.includes('saved')?cr('savedWord'):cr('lessonWord'))}</span><span class="small">${esc(cr('dailyCards'))}: ${goal}/5</span></div>${cardLoading?`<h1>${esc(cr('loading'))}</h1>`:finished?`<div class="review-finish"><div class="trophy" aria-hidden="true">✓</div><h1>${esc(cr('sessionDone'))}</h1><p class="muted">${esc(cardNotice||cr('comeBack'))}</p>${btn('continueCourse','cards-exit','primary')}</div>`:`<h1>${esc(cr(cardMode==='flip'?'flipTitle':'recallTitle'))}</h1><div class="review-modes"><button type="button" data-action="card-mode" data-mode="flip" class="${cardMode==='flip'?'active':''}" aria-pressed="${cardMode==='flip'}" ${cardFeedback?'disabled':''}>${esc(cr('flipMode'))}</button><button type="button" data-action="card-mode" data-mode="recall" class="${cardMode==='recall'?'active':''}" aria-pressed="${cardMode==='recall'}" ${cardFeedback?'disabled':''}>${esc(cr('recallMode'))}</button></div><div class="review-flashcard" dir="auto"><span class="small">${esc(cr(cardRevealed?'answerLabel':'clueLabel'))}</span><strong>${esc(cardRevealed?card.word:cardPrompt(card))}</strong>${cardRevealed&&cardPrompt(card)!==card.word?`<small>${esc(cardPrompt(card))}</small>`:''}</div>${cardMode==='flip'?`<div class="review-controls">${!cardRevealed?btn('flipCard','card-flip','primary'):btn('playWord','card-audio','quiet')}${cardRevealed?btn('again','card-again','quiet')+btn('knowIt','card-know','primary'):''}</div>`:`<div class="review-controls"><label class="field-label" lang="en" dir="ltr">${esc(cr('typeWord'))}<input id="card-input" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(cardInput)}" ${cardFeedback?'disabled':''}></label><div class="review-buttons">${btn('check','card-check','primary',cardInput.trim()&&!cardFeedback?'':'disabled')}${btn('showAnswer','card-reveal','quiet',cardFeedback?'disabled':'')}</div></div>${cardFeedback?`<p class="speech-status ${cardFeedback==='correct'?'speech-pass':''}" role="status">${esc(cr(cardFeedback==='correct'?'correctWord':'tryAgainWord'))}</p>${cardRevealed?`<div class="review-buttons">${btn('playWord','card-audio','quiet')}${btn('continue','card-next','primary')}</div>`:''}`:''}`}<p class="speech-note">${esc(cardNotice||cr('cardHint'))}</p>`}</section></div>`;}
