.transcript-details[open] .transcript{max-height:min(34dvh,250px);overflow:auto}
.vocab-flow-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.vocab-flow-grid .vocab-chip{justify-content:center;text-align:center;min-height:48px;font-weight:800;color:#203254;overflow-wrap:anywhere}
.speaking-card p{max-width:640px}
.speaking-prompt{background:#f2f5ff;border:1px solid #dce5f7;border-radius:14px;padding:16px;margin:10px 0 14px;font-size:clamp(16px,2vw,20px);line-height:1.5}
.assistant-link{align-self:flex-start;text-decoration:none;padding:11px 16px;border-radius:12px}
.speech-card{gap:10px}.speech-sentence{border:2px solid #dce5f7;background:#f6f8ff;border-radius:18px;padding:clamp(16px,3vh,26px);font-size:clamp(21px,3vw,30px);font-weight:800;line-height:1.35;color:#182b4c}.speech-sentence .speech-missed{background:#fff0da;border-bottom:3px solid #e7a63c;border-radius:3px}.speech-controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.speech-controls button{min-height:46px}.speech-status{margin:0;padding:10px 14px;border:1px solid #f0d5ae;border-radius:12px;background:#fff7eb;font-size:14px}.speech-status.speech-pass{border-color:#9fe4c4;background:#eafaf1}.speech-heard{margin:0;font-size:14px;line-height:1.45}.speech-heard span{display:inline-block;margin-inline-start:6px}.speech-note{margin:0;color:#687894;font-size:12px;line-height:1.4;max-width:600px}
@media(max-width:520px){
 body.is-learning main{height:calc(100vh - 64px);height:calc(100dvh - 64px);padding:7px 9px 9px}
 body.is-learning header{height:64px;padding:0 10px}
 .lesson-flow{gap:6px}
 .flow-top{height:34px;flex-basis:34px;gap:7px}
 .flow-top .quiet{padding:5px;font-size:12px;white-space:nowrap}
 .flow-top .pill{font-size:9px;letter-spacing:.7px;padding:5px 7px;white-space:nowrap}
 .flow-top .small{font-size:10px;white-space:nowrap}
 .flow-top .progress{height:7px;min-width:20px}
 .flow-card{padding:14px 13px;border-radius:18px}
 .flow-card h1{font-size:clamp(21px,6vw,26px);letter-spacing:-.45px;line-height:1.18;margin:7px 0 12px}
 .flow-card h2{font-size:18px;margin:7px 0}
 .flow-card>.pill{font-size:9px}
