 .question-card .option.selected{padding:9px 10px}
 .question-card .option .key{height:22px;width:22px}
 .question-card .field-label{font-size:11px;margin:7px 0}
 .question-card .field-label input{font-size:16px;padding:10px 11px}
 .question-audio{height:40px;margin:0 0 5px}
 .question-card .writing-label{font-size:11px;margin:6px 0}
 .writing-input{font-size:16px;min-height:68px;padding:10px 11px}
 .question-card .feedback{padding:10px;margin-top:8px}
 .question-card .feedback h2{font-size:16px}
 .question-card .feedback p{font-size:12px;line-height:1.4}
 .question-card .model{font-size:14px;padding:3px 0}
 .question-card .card-actions{padding-top:10px;margin-top:auto}
 .question-card .card-actions .primary{min-width:120px}
 .lesson-audio{margin:8px 0}
 .vocab-flow-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}
 .vocab-flow-grid .vocab-chip{min-height:40px;padding:8px;font-size:13px}
 .speaking-prompt{padding:12px;font-size:15px;margin:6px 0 10px}
 .assistant-link{font-size:13px;padding:9px 12px}
 .speech-card{gap:7px}.speech-sentence{font-size:clamp(18px,5vw,23px);padding:12px;line-height:1.28}.speech-controls{gap:8px}.speech-controls button{min-height:40px;padding:8px 10px;font-size:13px}.speech-status{padding:8px 10px;font-size:12px}.speech-heard{font-size:12px}.speech-note{font-size:11px}.speech-card .flow-actions .quiet{font-size:12px;padding:7px}
}
@media(max-width:380px){header{padding-left:7px;padding-right:7px}.brand{font-size:16px;letter-spacing:-.8px}.header-controls{gap:4px}#sound-toggle{font-size:10px;padding:8px 5px}.header-controls select{max-width:105px;padding:7px 3px}}
@media(max-height:700px){body.is-learning main{padding-top:5px;padding-bottom:6px}.flow-card{padding-top:11px;padding-bottom:11px}.flow-card h1{margin:5px 0 8px}.flow-card .intro-examples{margin:5px 0;padding:8px 10px}.flow-card .rule-list li{margin:3px 0}.question-card .options{margin:7px 0;gap:5px}.question-card .option{padding:8px 10px}.question-card .option.selected{padding:7px 9px}.question-card .feedback{padding:8px;margin-top:5px}.flow-actions{padding-top:6px}}

.sentence{display:flex;flex-wrap:wrap;align-items:center;gap:7px}.sentence .answer-tile{padding:7px 11px;font-size:inherit;line-height:1.2;background:#fff;border-color:#cbd8f4;box-shadow:0 2px 0 #e0e8f7}.sentence .answer-tile:hover:not(:disabled){background:#fff7e7;border-color:#f0c486}.order-hint{font-size:12px;color:var(--muted);margin:5px 2px 0;text-align:start}

.daily-goal{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:20px;padding:15px 18px;border:1px solid #cfdcf8;border-radius:18px;background:linear-gradient(120deg,#f5f8ff,#e9f1ff)}
.daily-goal strong{color:#172b4d}.daily-goal p{margin:4px 0;color:#51647f;font-size:14px}.daily-goal small{color:#3159ef;font-weight:800}.daily-goal .primary{white-space:nowrap}
.answer-detail{display:grid;gap:4px;padding:9px 12px;margin:7px 0;border-radius:11px;background:rgba(255,255,255,.68)}
.answer-detail span{font-size:12px;font-weight:700;color:#667895}.answer-detail strong{font-size:16px;color:#172b4d;overflow-wrap:anywhere}
.review-card{gap:10px}.review-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.review-card h1{margin:4px 0 2px}
.review-modes{display:flex;gap:8px}.review-modes button{flex:1;border:1px solid #cfdaf1;border-radius:12px;background:#f5f8ff;color:#3c5275;padding:10px 8px;font-weight:800}.review-modes button.active{background:#e7eeff;color:#3159ef;border-color:#829df6}
.review-flashcard{width:100%;min-height:150px;max-height:30dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;border:2px solid #cfdaf1;border-radius:22px;padding:16px;background:linear-gradient(145deg,#f6f9ff,#edf3ff);text-align:center}
.review-flashcard strong{font-size:clamp(23px,5vw,32px);line-height:1.24;color:#172b4d;overflow-wrap:anywhere}.review-flashcard small{font-size:13px;color:#60738f}.review-controls{display:grid;gap:9px}.review-controls>.field-label{width:100%;margin:0}.review-controls input{width:100%;padding:10px 12px;font-size:17px;border:2px solid #dce5f7;border-radius:11px}.review-buttons{display:flex;gap:8px;flex-wrap:wrap}.review-buttons button,.review-controls>button{min-height:43px}.review-finish{text-align:center}.review-finish .primary{margin-top:12px}.review-card .speech-note{min-height:18px}
@media(max-width:520px){.daily-goal{flex-direction:column;align-items:stretch;gap:9px}.daily-goal .primary{width:100%}.review-card{gap:7px}.review-card h1{font-size:clamp(19px,5.5vw,23px)}.review-modes button{font-size:12px;padding:8px 6px}.review-flashcard{min-height:118px;padding:10px;gap:5px}.review-flashcard strong{font-size:clamp(20px,6vw,25px)}.review-buttons button,.review-controls>button{padding:8px 10px;font-size:12px;min-height:38px}.review-controls input{font-size:15px;padding:8px 10px}.review-card .speech-status{margin:0}.vocab-card .flow-actions{gap:7px}.vocab-card .flow-actions .quiet{font-size:12px;padding:8px}}
@media(max-height:600px){.review-card{gap:5px}.review-flashcard{min-height:104px}.review-card h1{margin:2px 0}.review-card .speech-note{font-size:10px;margin:0}}

.answer-reviewed .question-audio{flex-shrink:0}.answer-reviewed .submitted-answer{font-size:13px;margin:4px 0;overflow-wrap:anywhere}.answer-reviewed .answer-detail blockquote{margin:4px 0;font-size:13px;line-height:1.35}.answer-reviewed h1{font-size:clamp(20px,3vw,32px)}

.skills-card{display:flex;flex-direction:column;min-height:0;gap:12px;padding:clamp(14px,2.2vw,30px)}
.skills-card>h1{font-size:clamp(22px,3vw,36px);line-height:1.15;flex:0 0 auto;margin:0}
.skills-body{min-height:0;flex:1;overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable;display:flex;flex-direction:column;gap:12px;padding:2px}
.skills-body h2{font-size:18px;line-height:1.3;margin:8px 0 2px}.skills-body p{margin:4px 0;line-height:1.5}
.skill-english{font-size:clamp(16px,2vw,22px);line-height:1.5;white-space:pre-wrap;text-align:start}
.reading-text{white-space:pre-wrap;line-height:1.55;font-size:clamp(15px,1.7vw,20px);padding:14px 16px;border-radius:16px;background:#eff3ff;flex-shrink:0;text-align:start}
.skills-card audio{width:100%;min-height:40px;flex-shrink:0}.skill-options{display:flex;flex-direction:column;gap:9px}
.skill-options .option{padding:10px 12px;min-height:44px;height:auto;display:flex;align-items:center;gap:12px;font-size:16px;text-align:start;flex-shrink:0}.skill-options .option span{color:#8192af;font-size:13px;flex-shrink:0}.skill-options .option.selected{border-color:#3159ef;background:#eef2ff}
.skills-card .flow-actions{flex-shrink:0;display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-top:0;padding-top:4px}.skills-card .flow-actions button{min-height:44px;padding:10px 16px;font-size:15px;max-width:100%;white-space:normal}.skills-card .flow-actions button:only-child{margin-inline-start:auto}
#skill-answer{width:100%;box-sizing:border-box;min-height:130px;flex:1;resize:vertical;max-height:280px;font:18px/1.55 system-ui;border:2px solid #dce4f4;border-radius:16px;padding:12px;color:#182542;background:#fff}
.skill-correction{background:#eff8f4;border-radius:12px;padding:12px;margin:10px 0}.skill-support{background:#f5f6fc;border-radius:12px;padding:10px}.skill-error{font-size:14px!important;color:#a23f27;padding:8px;background:#fff3ed;border-radius:10px;margin:0!important;max-height:70px;overflow:auto}
.skill-review{overflow-wrap:anywhere}.skill-map-tools{border-top:1px solid #dce4f4;margin-top:20px;padding-top:12px;font-size:14px}.skill-map-tools button,.skill-checkpoints button{font-size:13px;padding:8px 12px;min-height:40px;border-radius:12px;margin:5px 5px 5px 0;white-space:normal}.skill-checkpoints{display:flex;flex-wrap:wrap}.skill-scores{display:grid;grid-template-columns:1fr 1fr;gap:8px}.skill-match{display:flex;gap:8px;align-items:center;justify-content:space-between}.skill-match select{max-width:65%;min-height:40px}
#skills-sync-notice{position:fixed;top:62px;inset-inline:12px;z-index:10000;padding:6px 10px;background:#fff4d9;color:#674c15;border:1px solid #e8d4a9;border-radius:8px;font:12px/1.35 system-ui;max-height:36px;overflow:auto;pointer-events:none}#skills-sync-notice[hidden]{display:none}
@media(max-width:520px){.skills-card{gap:8px}.skills-card .flow-actions button{font-size:13px;padding:9px 12px}.skills-body{gap:9px}.skill-english{font-size:17px}.reading-text{font-size:15px;padding:10px 12px}#skill-answer{min-height:105px}.skills-body .small{font-size:12px}.record-controls{gap:7px}.record-controls button{font-size:13px;min-height:40px;padding:8px 12px}}

/* Same Evo-English components, shorter A2 learning steps. */
.a2-stage-bar{display:flex;flex-wrap:wrap;gap:5px;margin:0 0 8px;font-size:11px;line-height:1.3;color:#52627d}
.a2-stage-bar span{padding:5px 7px;border-radius:8px;background:#eaf0fb}
.a2-stage-bar [aria-current]{background:#3159ef;color:#fff;font-weight:700}
.a2-module-title{font-size:21px;line-height:1.3;padding:22px 0 4px;margin:0;position:relative;background:#f4f7fd;z-index:1}
.a2-checkpoint-card{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:20px;margin:12px 0 18px 54px;background:#edf2ff;border:1px solid #cbd7f8;border-radius:18px;position:relative;z-index:1}
.a2-checkpoint-card p{font-size:13px;margin:7px 0 0;color:#52627d}.a2-checkpoint-card button{min-height:44px;white-space:normal}
.a2-final{background:#eaf7f1;border-color:#bfdccb}.legacy-badge{color:#875920;background:#fff3d9;border-radius:8px;padding:6px 10px}
.skills-body{overflow-wrap:anywhere}.skills-body .reading-text{white-space:pre-line}.skill-review article{margin-bottom:12px}.skill-options .option{width:100%;min-height:48px;text-align:start}
.reading-text{line-height:1.6}.a2-stage-bar+ .flow-top{margin-top:0}.skill-scores{font-size:15px}
.a2-reading-note{background:#eef4ff;border-radius:10px;padding:10px 14px;font-size:14px}
@media(max-width:520px){.a2-module-title{font-size:18px}.a2-checkpoint-card{margin-left:0;flex-direction:column;align-items:stretch;padding:15px}.a2-stage-bar{font-size:10px;gap:3px}.a2-stage-bar span{padding:4px}.flow-top{gap:6px}.skills-card{padding:14px}.skill-scores{grid-template-columns:1fr}.progress-tools{display:flex;flex-wrap:wrap}}
.a2-stage-bar{flex-shrink:0}.skills-card{justify-content:flex-start}.skills-body{overflow-y:auto;max-height:none}.flow-actions{position:relative}
#a2-save-notice{position:fixed;bottom:8px;inset-inline:8px;background:#fff1d7;border:1px solid #dcb66d;color:#68460e;border-radius:12px;padding:12px;z-index:10000;max-height:120px;overflow:auto}#a2-save-notice[hidden]{display:none}
